args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?label (COALESCE(?bd, ?bd2) AS ?birthDate) WHERE {
  VALUES ?person { dbr:Katrien_Aerts dbr:Giuliano_Rossi }
  OPTIONAL { ?person dbo:birthDate ?bd. }
  OPTIONAL { ?person dbp:birthDate ?bd2. }
  OPTIONAL { ?person rdfs:label ?label. FILTER(lang(?label) = "en" || lang(?label) = "") }
}
ORDER BY ?birthDate

